148	/**
149	 * Processes tool result blocks from a user message, matching them to pending
150	 * tool invocations and marking them as complete.
151	 */
152	function processToolResults(content: string | ContentBlock[], toolContext: ToolContext): void {
153		if (typeof content === 'string') {
154			return;
155		}
156	
157		for (const block of content) {
158			if (isToolResultBlock(block)) {
159				const toolUse = toolContext.unprocessedToolCalls.get(block.tool_use_id);
160				if (toolUse && isToolUseBlock(toolUse)) {
161					toolContext.unprocessedToolCalls.delete(block.tool_use_id);
162					const pendingInvocation = toolContext.pendingToolInvocations.get(block.tool_use_id);
163					if (pendingInvocation) {
164						pendingInvocation.isComplete = true;
165						pendingInvocation.isConfirmed = true;
166						pendingInvocation.isError = block.is_error;
167						// Populate tool output for display in chat UI
168						completeToolInvocation(toolUse, block, pendingInvocation);
169						toolContext.pendingToolInvocations.delete(block.tool_use_id);
170					}
171				}
172			}
173		}
174	}
