100	function mapHistoryForSnapshot(history: readonly (vscode.ChatRequestTurn | vscode.ChatResponseTurn2)[]): SnapshotTurn[] {
101		return history.map(turn => {
102			if (turn instanceof ChatRequestTurn || turn instanceof ChatRequestTurn2) {
103				return {
104					type: 'request',
105					prompt: turn.prompt,
106				};
107			} else if (turn instanceof ChatResponseTurn2) {
108				return {
109					type: 'response',
110					parts: turn.response.map(part => {
111						if (part instanceof ChatResponseMarkdownPart) {
112							return {
113								type: 'markdown',
114								content: part.value.value,
115							};
116						} else if (part instanceof ChatToolInvocationPart) {
117							return {
118								type: 'tool',
119								toolName: part.toolName,
120								toolCallId: part.toolCallId,
121								isError: part.isError,
122								isComplete: part.isComplete,
123							};
124						} else if (part instanceof ChatResponseThinkingProgressPart) {
125							return {
126								type: 'thinking',
127							};
128						}
129						return { type: 'unknown' };
130					}),
131				};
132			}
133			return { type: 'unknown' };
134		});
135	}
