 * Builds a map from a subagent's `parentToolUseId` to the subagent, for quick lookup
 * when linking subagent tool calls under their spawning Agent/Task tool invocation.
 *
 * Subagents without a `parentToolUseId` cannot be correlated to a parent tool call
 * and are excluded entirely.
 */
function buildSubagentMapByParentToolUseId(subagents: readonly ISubagentSession[]): Map<string, ISubagentSession> {
	const map = new Map<string, ISubagentSession>();
	for (const subagent of subagents) {
		if (subagent.parentToolUseId) {
			map.set(subagent.parentToolUseId, subagent);
		}
	}
	return map;
}

/**
 * Collects the tool_use ids of every Agent or Task tool call in the session's
 * assistant messages. These are the only tool calls that can spawn a subagent.
 */
function collectParentToolUseIds(messages: readonly StoredMessage[]): Set<string> {
	const ids = new Set<string>();
	for (const msg of messages) {
		if (msg.type === 'assistant' && msg.message.role === 'assistant') {
			for (const block of (msg.message as AssistantMessageContent).content) {
				if (isToolUseBlock(block) && (block.name === ClaudeToolNames.Task || block.name === ClaudeToolNames.Agent)) {
					ids.add(block.id);
				}
			}
		}
	}
	return ids;
}

